def main():
    links=read('02-links');buttons=read('02-buttons');console=read('03-console');layout=read('04-layout');access=read('07-accessibility');lh=read('09-lighthouse');scenarios=read('10-scenarios');stability=read('05-stability');motion=read('06-motion');materials=read('17-materials');public=read('18-public');weight=read('09-weight');quiz=read('10-quiz-exhaustive');contrast=read('08-contrast')
